/**
 * Order persistence ledger (P209).
 *
 * Provides a simple append-only JSONL-backed order system.
 * Orders are stored in `.state/orders.jsonl` by default, but every
 * function accepts an optional `basePath` for testability.
 *
 * Uses only Node.js built-in modules — no external dependencies.
 */

import { readFileSync, writeFileSync, appendFileSync, existsSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { randomUUID } from "node:crypto";

// ── Interfaces ────────────────────────────────────────────────────────

/** A single order in the ledger. */
export interface Order {
  id: string;
  text: string;
  from: string;
  createdAt: string;
  completedAt?: string;
  status: "active" | "completed";
}

// ── Helpers ───────────────────────────────────────────────────────────

/** Default base path for the JSONL file. */
const DEFAULT_BASE = join(process.cwd(), ".state");

/** Resolve the full path to the orders JSONL file. */
function filePath(basePath: string): string {
  return join(basePath, "orders.jsonl");
}

/**
 * Ensure the target directory exists (creates it recursively if needed).
 */
function ensureDir(basePath: string): void {
  if (!existsSync(basePath)) {
    mkdirSync(basePath, { recursive: true });
  }
}

/**
 * Read and parse every valid JSON line from the orders file.
 * Silently skips empty or corrupt lines.
 */
function readAll(basePath: string): Order[] {
  const fp = filePath(basePath);
  if (!existsSync(fp)) return [];

  const raw = readFileSync(fp, "utf-8");
  const orders: Order[] = [];

  for (const line of raw.split("\n")) {
    const trimmed = line.trim();
    if (trimmed.length === 0) continue;
    try {
      orders.push(JSON.parse(trimmed) as Order);
    } catch {
      // skip corrupt lines
    }
  }

  return orders;
}

/**
 * Rewrite the entire JSONL file from an array of orders.
 */
function writeAll(orders: Order[], basePath: string): void {
  ensureDir(basePath);
  const content = orders.map((o) => JSON.stringify(o)).join("\n") + "\n";
  writeFileSync(filePath(basePath), content, "utf-8");
}

// ── Public API ────────────────────────────────────────────────────────

/**
 * Create a new active order and append it to the ledger.
 *
 * @param text  Human-readable description of the order.
 * @param from  Who issued the order (e.g. "human", "bob").
 * @param basePath  Directory containing `orders.jsonl` (default `.state/`).
 * @returns The newly created Order.
 */
export function addOrder(
  text: string,
  from: string,
  basePath: string = DEFAULT_BASE,
): Order {
  ensureDir(basePath);

  const order: Order = {
    id: randomUUID(),
    text,
    from,
    createdAt: new Date().toISOString(),
    status: "active",
  };

  appendFileSync(filePath(basePath), JSON.stringify(order) + "\n", "utf-8");
  return order;
}

/**
 * Retrieve orders from the ledger, optionally filtering by status.
 *
 * @param filter  `"active"` (default), `"completed"`, or `"all"`.
 * @param basePath  Directory containing `orders.jsonl` (default `.state/`).
 * @returns Matching orders (empty array if file doesn't exist).
 */
export function getOrders(
  filter: "active" | "completed" | "all" = "active",
  basePath: string = DEFAULT_BASE,
): Order[] {
  const all = readAll(basePath);
  if (filter === "all") return all;
  return all.filter((o) => o.status === filter);
}

/**
 * Mark an active order as completed.
 *
 * @param id  The UUID of the order to complete.
 * @param basePath  Directory containing `orders.jsonl` (default `.state/`).
 * @returns The updated Order, or `null` if no matching active order exists.
 */
export function completeOrder(
  id: string,
  basePath: string = DEFAULT_BASE,
): Order | null {
  const all = readAll(basePath);
  const target = all.find((o) => o.id === id && o.status === "active");

  if (!target) return null;

  target.status = "completed";
  target.completedAt = new Date().toISOString();

  writeAll(all, basePath);
  return target;
}

/**
 * Growth lifecycle utilities for the coach's experiment pipeline.
 *
 * Manages promotion and discard of agent forks created during
 * growth-cycle and training-sprint workflows.
 *
 * Forks live in `<agentsRoot>/.lab/<forkName>/` and contain
 * modified copies of agent files (SOUL.md, heartbeat.md, skills/, etc.).
 *
 * - promoteAgent: copies changed files from a fork back to the
 *   canonical agent directory, then removes the fork.
 * - discardAgent: removes a fork directory without applying changes.
 */

import { readdirSync, cpSync, mkdirSync, rmSync, existsSync } from "node:fs";
import { join, relative, dirname } from "node:path";

export interface GrowthConfig {
  /** Root directory containing agent directories (e.g., /app/agents) */
  agentsRoot: string;
}

export interface PromoteResult {
  /** List of relative file paths that were copied from the fork to the target agent */
  promoted: string[];
}

/**
 * Promote a lab fork by copying its files into the canonical agent directory.
 *
 * Walks the fork directory recursively and copies all files to the
 * corresponding location under `<agentsRoot>/<targetAgent>/`.
 * After copying, removes the fork directory.
 *
 * @param config - Growth config with agentsRoot path
 * @param forkName - Name of the fork directory under .lab/
 * @param targetAgent - Name of the canonical agent to overwrite
 * @returns Object with list of promoted file paths
 * @throws If the fork directory doesn't exist
 */
export function promoteAgent(
  config: GrowthConfig,
  forkName: string,
  targetAgent: string,
): PromoteResult {
  const labDir = join(config.agentsRoot, ".lab");
  const forkDir = join(labDir, forkName);
  const targetDir = join(config.agentsRoot, targetAgent);

  if (!existsSync(forkDir)) {
    throw new Error(`Fork not found: ${forkDir}`);
  }

  const promoted: string[] = [];

  // Recursively collect all files in the fork
  function walkDir(dir: string): void {
    const entries = readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = join(dir, entry.name);
      if (entry.isDirectory()) {
        walkDir(fullPath);
      } else if (entry.isFile()) {
        const relPath = relative(forkDir, fullPath);
        const destPath = join(targetDir, relPath);
        // Ensure parent directory exists (fork may contain nested dirs)
        mkdirSync(dirname(destPath), { recursive: true });
        cpSync(fullPath, destPath, { force: true });
        promoted.push(relPath);
      }
    }
  }

  walkDir(forkDir);

  // Clean up the fork after successful promotion
  rmSync(forkDir, { recursive: true, force: true });

  return { promoted };
}

/**
 * Discard a lab fork by removing its directory.
 *
 * @param config - Growth config with agentsRoot path
 * @param forkName - Name of the fork directory under .lab/
 * @throws If the fork directory doesn't exist
 */
export function discardAgent(
  config: GrowthConfig,
  forkName: string,
): void {
  const labDir = join(config.agentsRoot, ".lab");
  const forkDir = join(labDir, forkName);

  if (!existsSync(forkDir)) {
    throw new Error(`Fork not found: ${forkDir}`);
  }

  rmSync(forkDir, { recursive: true, force: true });
}

/**
 * Ops Gate Logging (P61).
 *
 * Provides append-only JSONL-backed ops-receipt logging.
 * Receipts are stored in `.state/ops-receipts.jsonl` by default, but every
 * function accepts an optional `basePath` for testability.
 *
 * Uses only Node.js built-in modules — no external dependencies.
 */

import { readFileSync, appendFileSync, existsSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { randomUUID } from "node:crypto";

// ── Interfaces ────────────────────────────────────────────────────────

/** A single ops receipt entry. */
export interface OpsReceipt {
  id: string;
  action: string;
  result: string;
  context: Record<string, unknown>;
  timestamp: string;
  agent?: string;
}

// ── Helpers ───────────────────────────────────────────────────────────

/** Default base path for the JSONL file. */
const DEFAULT_BASE = join(process.cwd(), ".state");

/** Resolve the full path to the ops-receipts JSONL file. */
function filePath(basePath: string): string {
  return join(basePath, "ops-receipts.jsonl");
}

/**
 * Ensure the target directory exists (creates it recursively if needed).
 */
function ensureDir(basePath: string): void {
  if (!existsSync(basePath)) {
    mkdirSync(basePath, { recursive: true });
  }
}

/**
 * Read and parse every valid JSON line from the receipts file.
 * Silently skips empty or corrupt lines.
 */
function readAll(basePath: string): OpsReceipt[] {
  const fp = filePath(basePath);
  if (!existsSync(fp)) return [];

  const raw = readFileSync(fp, "utf-8");
  const receipts: OpsReceipt[] = [];

  for (const line of raw.split("\n")) {
    const trimmed = line.trim();
    if (trimmed.length === 0) continue;
    try {
      receipts.push(JSON.parse(trimmed) as OpsReceipt);
    } catch {
      // skip corrupt lines
    }
  }

  return receipts;
}

// ── Public API ────────────────────────────────────────────────────────

/**
 * Log an ops receipt and append it to the ledger.
 *
 * @param action   The action performed (e.g. "deploy", "rollback").
 * @param result   Outcome description (e.g. "success", "failed").
 * @param context  Arbitrary metadata object. If it contains an `agent`
 *                 property (string), that value is promoted to the
 *                 top-level `agent` field on the receipt.
 * @param basePath Directory containing `ops-receipts.jsonl` (default `.state/`).
 */
export function logOpsReceipt(
  action: string,
  result: string,
  context: Record<string, unknown>,
  basePath: string = DEFAULT_BASE,
): void {
  ensureDir(basePath);

  const receipt: OpsReceipt = {
    id: randomUUID(),
    action,
    result,
    context,
    timestamp: new Date().toISOString(),
  };

  // Promote agent from context if available
  if (typeof context.agent === "string") {
    receipt.agent = context.agent;
  }

  appendFileSync(filePath(basePath), JSON.stringify(receipt) + "\n", "utf-8");
}

/**
 * Retrieve receipts from the ledger, optionally filtering.
 *
 * @param filter    Optional filter: `action` matches exact action string,
 *                  `since` keeps only receipts whose timestamp >= the value.
 * @param basePath  Directory containing `ops-receipts.jsonl` (default `.state/`).
 * @returns Matching receipts (empty array if file doesn't exist).
 */
export function getReceipts(
  filter?: { action?: string; since?: string },
  basePath: string = DEFAULT_BASE,
): OpsReceipt[] {
  let receipts = readAll(basePath);

  if (filter?.action) {
    receipts = receipts.filter((r) => r.action === filter.action);
  }

  if (filter?.since) {
    receipts = receipts.filter((r) => r.timestamp >= filter.since);
  }

  return receipts;
}

/**
 * Experience Replay Enforcement (P114).
 *
 * Blocks complex state-changing actions if the agent hasn't checked its
 * error logs recently.  Builds on top of the ops-gate logging system
 * (`ops-gate.ts`) — receipts with `action === "error-log-review"` are
 * used as proof that the agent has reviewed its error logs.
 *
 * Uses only Node.js built-in modules + the local ops-gate module.
 */

import { join } from "node:path";
import { getReceipts, logOpsReceipt } from "./ops-gate.js";

// ── Constants ─────────────────────────────────────────────────────────

/** Actions that require a recent error-log review before execution. */
export const CRITICAL_ACTIONS = [
  "deploy",
  "rollback",
  "delete",
  "promote",
  "discard",
  "git-push",
  "schema-migrate",
] as const;

/** How far back to look for an error-log review (2 hours). */
const SESSION_WINDOW_MS = 2 * 60 * 60 * 1000;

// ── Helpers ───────────────────────────────────────────────────────────

/** Default base path for the JSONL file. */
const DEFAULT_BASE = join(process.cwd(), ".state");

// ── Public API ────────────────────────────────────────────────────────

/**
 * Check whether the error log has been reviewed in the current session
 * (last 2 hours).
 *
 * @param basePath  Directory containing `ops-receipts.jsonl` (default `.state/`).
 * @returns `true` if a recent `error-log-review` receipt exists.
 */
export function checkErrorLogReviewed(
  basePath: string = DEFAULT_BASE,
): boolean {
  const since = new Date(Date.now() - SESSION_WINDOW_MS).toISOString();
  const receipts = getReceipts({ action: "error-log-review", since }, basePath);
  return receipts.length > 0;
}

/**
 * Enforce the replay check before a state-changing action.
 *
 * - If error log has been reviewed → allowed.
 * - If not reviewed AND action is critical → blocked.
 * - If not reviewed but action is non-critical → allowed.
 *
 * @param intendedAction  The action the agent wants to perform.
 * @param basePath        Directory containing `ops-receipts.jsonl` (default `.state/`).
 * @returns `{ allowed, reason }` describing whether the action may proceed.
 */
export function enforceReplayCheck(
  intendedAction: string,
  basePath: string = DEFAULT_BASE,
): { allowed: boolean; reason: string } {
  const reviewed = checkErrorLogReviewed(basePath);

  if (reviewed) {
    return { allowed: true, reason: "Error log reviewed" };
  }

  if ((CRITICAL_ACTIONS as readonly string[]).includes(intendedAction)) {
    return {
      allowed: false,
      reason:
        `Must review error logs before performing: ${intendedAction}. ` +
        `Call logOpsReceipt('error-log-review', ...) after checking errors.`,
    };
  }

  return { allowed: true, reason: "Non-critical action, no review required" };
}

/**
 * Convenience function: mark the error log as reviewed by logging an
 * ops receipt with `action === "error-log-review"`.
 *
 * @param agent     Who performed the review (default `"unknown"`).
 * @param basePath  Directory containing `ops-receipts.jsonl` (default `.state/`).
 */
export function markErrorLogReviewed(
  agent?: string,
  basePath: string = DEFAULT_BASE,
): void {
  logOpsReceipt(
    "error-log-review",
    "reviewed",
    { agent: agent ?? "unknown" },
    basePath,
  );
}
